package main

// Official, unmodified OpenID sign-in image supplied for third-party websites:
// https://shared.fastly.steamstatic.com/community_assets/images/steamworks_docs/english/sits_large_border.png
// SHA-256: a8ce76bb630ac20d6a7b7b26db0e8464709188a5f234d54eaf8be8c96d605dcc
// See docs/games/VISUAL_EXPERIENCE.md. This image is not used as a native app logo.

import (
	"html/template"
	"net/http"
)

var steamSignInPage = template.Must(template.New("steam-sign-in").Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Link Steam · PlezyNG</title><style>html{color-scheme:light dark}body{margin:0;padding:24px;font:1rem/1.6 system-ui,sans-serif;background:#f7f7f8;color:#111}main{max-width:36rem;margin:8vh auto}h1{line-height:1.2;font-size:2rem}a{display:inline-flex;align-items:center;min-height:48px;padding:12px 0}a:focus-visible{outline:3px solid currentColor;outline-offset:6px;border-radius:4px}img{max-width:100%;object-fit:contain}footer,.hint{font-size:.875rem}.source{font-weight:600}@media(prefers-color-scheme:dark){body{background:#0e0f12;color:#ededed}}</style></head><body><main>
<p class="source">PlezyNG · Steam connection</p><h1>Link your Steam library</h1>
<p>Continue to steamcommunity.com to sign in. Your Steam password stays with Steam.</p>
<p>Linking imports your game library. Streaming also needs a paired computer running Steam Remote Play.</p>
<a href="{{.}}" rel="noreferrer"><img src="data:image/png;base64," width="118" height="51" alt="Sign in through Steam"></a>
<p class="hint">After signing in, return to PlezyNG. If this link has expired, start again in the app.</p>
<footer>©2026 Valve Corporation. Steam and the Steam logo are trademarks and/or registered trademarks of Valve Corporation in the U.S. and/or other countries. PlezyNG is an independent application.</footer>
</main></body></html>`))

func renderSteamSignIn(w http.ResponseWriter, target string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store, private")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	w.Header().Set("Content-Security-Policy", "default-src 'none'; img-src data:; style-src 'sha256-FSTGPG9zNE5KXvQ5zckAl0U5U9gHvGzWHT2u3yqwHkY='; base-uri 'none'; frame-ancestors 'none'; form-action 'none'")
	_ = steamSignInPage.Execute(w, target)
}
